use crate::errors::{Result, AppError}; use tauri::{AppHandle, Manager}; use std::fs; use std::path::PathBuf; #[tauri::command] pub fn backup_database(app_handle: AppHandle, destination: String) -> Result<()> { let app_dir = app_handle.path().app_data_dir().expect("Failed to get app data dir"); let db_path = app_dir.join("sari_sari.db"); let dest_path = PathBuf::from(destination); fs::copy(db_path, dest_path).map_err(|e| AppError::Internal(format!("Failed to backup: {}", e)))?; Ok(()) } #[tauri::command] pub fn restore_database(app_handle: AppHandle, source: String) -> Result<()> { let app_dir = app_handle.path().app_data_dir().expect("Failed to get app data dir"); let db_path = app_dir.join("sari_sari.db"); let source_path = PathBuf::from(source); fs::copy(source_path, db_path).map_err(|e| AppError::Internal(format!("Failed to restore: {}", e)))?; Ok(()) }
